        UNION { VALUES ?root { wd:Q899698 wd:Q28456139 wd:Q118870638 wd:Q7858735 wd:Q131544290 wd:Q250509 wd:Q77358734 wd:Q47103999 wd:Q7883028 wd:Q3115587 wd:Q15098457 wd:Q609057 wd:Q7885139 wd:Q7885148 wd:Q16956925 wd:Q6853740 wd:Q20878963 wd:Q7894169 wd:Q26789594 wd:Q597663 } ?item wdt:P279 ?root }
        UNION { VALUES ?root { wd:Q899698 wd:Q28456139 wd:Q118870638 wd:Q7858735 wd:Q131544290 wd:Q250509 wd:Q77358734 wd:Q47103999 wd:Q7883028 wd:Q3115587 wd:Q15098457 wd:Q609057 wd:Q7885139 wd:Q7885148 wd:Q16956925 wd:Q6853740 wd:Q20878963 wd:Q7894169 wd:Q26789594 wd:Q597663 } BIND(?root AS ?item) }
